<?php require_once __DIR__.'/../includes/functions.php';require_role('admin');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??'');$s=$pdo->prepare("INSERT INTO timetables(class_id,division_id,day_name,period_no,start_time,end_time,subject_id,teacher_id,room) VALUES(?,?,?,?,?,?,?,?,?)");$s->execute([(int)$_POST['class_id'],(int)$_POST['division_id'],$_POST['day_name'],(int)$_POST['period_no'],$_POST['start_time'],$_POST['end_time'],(int)$_POST['subject_id'],(int)$_POST['teacher_id'],$_POST['room']]);header('Location:timetable.php');exit;}$classes=$pdo->query("SELECT id,name FROM classes")->fetchAll();$divisions=$pdo->query("SELECT id,name FROM divisions")->fetchAll();$subjects=$pdo->query("SELECT id,name FROM subjects")->fetchAll();$teachers=$pdo->query("SELECT id,first_name,last_name FROM teachers")->fetchAll();$rows=$pdo->query("SELECT t.day_name,t.period_no,t.start_time,t.end_time,c.name class_name,d.name division_name,s.name subject_name,CONCAT(th.first_name,' ',th.last_name) teacher_name,t.room FROM timetables t JOIN classes c ON c.id=t.class_id JOIN divisions d ON d.id=t.division_id JOIN subjects s ON s.id=t.subject_id JOIN teachers th ON th.id=t.teacher_id ORDER BY t.period_no")->fetchAll();$pageTitle='Timetable';$base='../';require __DIR__.'/../includes/header.php';?><div class="layout"><?php require __DIR__.'/../includes/sidebar.php';?><section class="content"><div class="card"><h1>Timetable</h1><div class="table-wrap"><table class="table"><tr><?php if($rows)foreach(array_keys($rows[0]) as $h):?><th><?=e($h)?></th><?php endforeach;?></tr><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=e((string)$v)?></td><?php endforeach;?></tr><?php endforeach;?></table></div></div><div class="card" style="margin-top:18px"><h2>Add Entry</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Class<select name="class_id"><?php foreach($classes as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></label><label>Division<select name="division_id"><?php foreach($divisions as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></label><label>Day<select name="day_name"><?php foreach(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'] as $x):?><option><?=$x?></option><?php endforeach;?></select></label><label>Period<input type="number" name="period_no" required></label><label>Start<input type="time" name="start_time" required></label><label>End<input type="time" name="end_time" required></label><label>Subject<select name="subject_id"><?php foreach($subjects as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></label><label>Teacher<select name="teacher_id"><?php foreach($teachers as $x):?><option value="<?=$x['id']?>"><?=e($x['first_name'].' '.$x['last_name'])?></option><?php endforeach;?></select></label><label>Room<input name="room"></label><button class="btn">Save</button></form></div></section></div><?php require __DIR__.'/../includes/footer.php';?>